fn get_min_val(a: &Vec<i8>) -> i8 {
    // assume a.len() >= 1
    let mut min_val = a[0];
    for &x in a.iter().skip(1) {
        if x < min_val {
            min_val = x;
        }
    }
    min_val
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // assume a.len() >= 1
    let mut max_val = a[0];
    for &x in a.iter().skip(1) {
        if x > max_val {
            max_val = x;
        }
    }
    max_val
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    // assume a.len() >= 1 and 0 <= q <= 100
    assert!(0 <= q && q <= 100, "quantile must be between 0 and 100");

    let min = get_min_val(&a);
    let max = get_max_val(&a);

    // Work in i16 to avoid overflow when computing (max-min)*q
    let diff = (max as i16) - (min as i16);
    let scaled = diff * (q as i16) / 100;

    // Add back to the min
    (min as i16 + scaled) as i8
}

