    #[test]
    fn test_nanquantile_endpoints() {
        let a = vec![5, 2, 8, -3, 4];
        assert_eq!(nanquantile(a.clone(), 0), -3);
        assert_eq!(nanquantile(a.clone(), 100), 8);
    }

    #[test]
    fn test_nanquantile_middle() {
        let a = vec![-10, 10];
        // For q=50 on [-10,10], we get -10 + (20*50/100) = -10 + 10 = 0
        assert_eq!(nanquantile(a.clone(), 50), 0);

        // A more skewed example
        let b = vec![0, 100];
        // q=25 gives 0 + (100*25/100) = 25
        assert_eq!(nanquantile(b.clone(), 25), 25);
        // q=75 gives 75
        assert_eq!(nanquantile(b.clone(), 75), 75);
    }
